<style>
.boleta-documento{font-family:DejaVu Sans,Arial,sans-serif;color:#0c2144;background:white;padding:18px;font-size:10px}.boleta-encabezado{display:table;width:100%;border-bottom:3px solid #0d3a67;padding-bottom:12px}.boleta-logo{width:86px;float:left;margin-right:15px}.boleta-encabezado h1{font-size:20px;margin:12px 0 2px;color:#0a274e;text-align:center}.boleta-encabezado p,.boleta-encabezado small{text-align:center;display:block;letter-spacing:2px;margin:3px}.boleta-documento h2{text-align:center;background:#0a2c55;color:white;border-radius:5px;font-size:19px;padding:12px;margin:17px 0 0}.boleta-documento h3{text-align:center;background:#f4e8d9;color:#0a2c55;padding:6px;margin:0 auto 15px;width:40%;font-size:13px}.boleta-datos,.boleta-notas,.boleta-firmas{width:100%;border-collapse:collapse}.boleta-datos th{background:#0e365f;color:white;text-align:left;width:15%;padding:8px}.boleta-datos td{border:1px solid #b9cbdc;padding:8px}.boleta-notas{margin-top:14px}.boleta-notas th{background:#0b365f;color:white;padding:7px 4px;font-size:9px}.boleta-notas td{border:1px solid #bac7d7;padding:6px 3px;text-align:center;font-size:9px}.boleta-notas tr:nth-child(even){background:#edf3f8}.boleta-notas .boleta-materia{text-align:left}.boleta-notas .boleta-promedios th{background:#f3e7d9;color:#0c2144;border:1px solid #c9c1b7}.boleta-observaciones{margin-top:18px;border:1px solid #b7c6d6;border-radius:6px;padding:10px;min-height:65px}.boleta-observaciones strong{color:#b82335}.boleta-observaciones p{color:#8290a0}.boleta-firmas{margin-top:55px}.boleta-firmas td{text-align:center;width:50%;line-height:1.8}.boleta-documento footer{margin-top:28px;background:#0b315d;color:white;padding:10px;font-size:9px}.boleta-documento footer span{float:right}.boleta-parcial{color:#8c4a13;font-size:9px;margin-top:8px}@media print{.boleta-documento{padding:0}}
